{
  "checks": [
    {
      "claim_id": "claim.7bb4e011e39ca280c11cbcf5",
      "candidate_id": "node.ad3ed6f7c586444ec7213491",
      "source_support": {
        "status": "SUPPORTED",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u29.4630",
            "quote": "In assessing whether the complex product designation is warranted7, the SFC will adopt a holistic approach taking into account the specific circumstances of the case."
          },
          {
            "unit_id": "d4148dd852cee.u64.8910",
            "quote": "In cases where the Fund’s aggregate direct and indirect exposures to private market assets are less than 50% of the Fund’s NAV."
          }
        ],
        "rationale": "The assessment provision and footnote 7 expressly establish holistic assessment below 50%; below-threshold exposure does not exclude designation."
      },
      "question_relation": {
        "status": "RELEVANT",
        "question_hash": "667e02878245fac215d7cc7676acbdd52b486e17dea8e9eed9ea5b37ad03a712",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u21.3779",
            "quote": "On a case-by-case basis, the SFC may also designate a Fund as a complex product, taking into account factors including, without limitation:"
          }
        ],
        "rationale": "This establishes the alternative classification route when the automatic threshold is not met."
      },
      "executable_correspondence": {
        "status": "PRESERVES",
        "representation_quotes": [
          "applicable_sfc_designation: The SFC has actually made a case-specific complex-product designation for this Fund that applies at the assessment time. Unknown designation evidence leaves this fact unknown. (Boolean for an applicable SFC decision concerning the assessed fund)",
          "Result: at least one of these conditions holds: [[[[the fact direct_exposure] plus [the fact indirect_exposure]] plus [[the fact direct_exposure] plus [the fact indirect_exposure]]] is greater than or equal to [the fact nav]; the fact applicable_sfc_designation]"
        ],
        "rationale": "Within executable scope, an applicable designation can establish classification below 50%. The rule consumes an actual decision and does not purport to conduct the holistic assessment. The additional NAV scope restriction is assessed separately."
      },
      "authority": {
        "status": "NONE_DECLARED",
        "dependency_ids": [],
        "rationale": "The circular and footnote 7 suffice for this proposition. Evidence of an individual designation is an unresolved factual input, not an additional authority needed to establish the route."
      },
      "followup_questions": []
    },
    {
      "claim_id": "claim.7d8dee41528186a056fb4c5f",
      "candidate_id": "node.ad3ed6f7c586444ec7213491",
      "source_support": {
        "status": "SUPPORTED",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u58.7778",
            "quote": "Direct investments in/exposures to private assets fall within the investment limit of 15% of a Fund’s total net asset value (NAV) under 7.3 of the Code on Unit Trusts and Mutual Funds (UT Code)."
          },
          {
            "unit_id": "d4148dd852cee.u21.3779",
            "quote": "A Fund will be considered as a complex product if its total direct and indirect exposures to private market assets amount to 50% or more of the Fund’s NAV."
          }
        ],
        "rationale": "The circular states the direct-investment limit separately from the aggregate-exposure classification threshold. The incorporated provision's full qualifications are not supplied."
      },
      "question_relation": {
        "status": "NOT_APPLICABLE_TO_THIS_QUESTION",
        "question_hash": "667e02878245fac215d7cc7676acbdd52b486e17dea8e9eed9ea5b37ad03a712",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u58.7778",
            "quote": "Direct investments in/exposures to private assets fall within the investment limit of 15% of a Fund’s total net asset value (NAV) under 7.3 of the Code on Unit Trusts and Mutual Funds (UT Code)."
          }
        ],
        "rationale": "The exact question concerns classification under two retained routes, not compliance with investment restrictions. This limit neither replaces the 50% threshold nor creates another classification route."
      },
      "executable_correspondence": {
        "status": "NOT_APPLICABLE",
        "representation_quotes": [],
        "rationale": "A 15% investment-limit compliance test is outside this classification question. Its absence is not a classification-code defect and does not authorize excess investment."
      },
      "authority": {
        "status": "MISSING",
        "dependency_ids": [],
        "rationale": "UT Code section 7.3 is needed to resolve the incorporated limit's full application. It is absent, and no supplied dependency ID is identifiably mapped to it."
      },
      "followup_questions": [
        "Can the applicable UT Code section 7.3, including its qualifications, be supplied and mapped to a dependency ID for any separate investment-limit assessment?"
      ]
    },
    {
      "claim_id": "claim.826cbb55be5fd7cfdb3c204f",
      "candidate_id": "node.ad3ed6f7c586444ec7213491",
      "source_support": {
        "status": "SUPPORTED",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u62.8487",
            "quote": "For example, Total Return Swaps on indices with exposure to leveraged loans or broadly syndicated loans (TRSs), or Significant Risk Transfers with underlying assets that are corporate loans (SRTs)."
          },
          {
            "unit_id": "d4148dd852cee.u59.7979",
            "quote": "The examples of indirect exposures set out in paragraph 1 above are non-exhaustive, and subject to review and update by the SFC from time to time in view of market developments."
          }
        ],
        "rationale": "The footnotes support the specified examples and their non-exhaustive character. Instrument names alone do not establish exposure amounts."
      },
      "question_relation": {
        "status": "RELEVANT",
        "question_hash": "667e02878245fac215d7cc7676acbdd52b486e17dea8e9eed9ea5b37ad03a712",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u1.5",
            "quote": "indirect exposures2 including through investments in business development companies (BDCs)3, collateralised loan obligations (CLOs)4 or financial derivative instruments5."
          }
        ],
        "rationale": "The examples inform which derivative exposures may enter the aggregate classification input; they are not independent triggers."
      },
      "executable_correspondence": {
        "status": "OMITS",
        "representation_quotes": [
          "indirect_exposure: Aggregate indirect exposure to private credit and private equity through all relevant holdings and instruments, including qualifying exposures beyond the listed examples, measured under the supplied methodology at the assessment time. (Exact common valuation units, identical to those used for direct_exposure and nav)",
          "Supplied classifications requiring judgment: is_laf, direct_exposure, indirect_exposure, nav, applicable_sfc_designation. Their assessment is not implemented by this formula."
        ],
        "rationale": "The executable does not identify or measure the specified TRS and SRT exposures. Its aggregate input is compatible with their inclusion, so this omission concerns upstream input assessment, not a demonstrated exclusion or arithmetic defect."
      },
      "authority": {
        "status": "NONE_DECLARED",
        "dependency_ids": [],
        "rationale": "The circular supplies the examples directly. Their actual measurement remains unresolved without establishing that a particular additional external authority is required."
      },
      "followup_questions": [
        "What supplied methodology identifies and measures these TRS and SRT exposures, and does it rely on additional external authority?"
      ]
    },
    {
      "claim_id": "claim.8b0bc972e5f24537607f83e7",
      "candidate_id": "node.ad3ed6f7c586444ec7213491",
      "source_support": {
        "status": "SUPPORTED",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u65.9044",
            "quote": "Paragraph 5.5 of the SFC’s Code of Conduct for Persons Licensed by or Registered with the Securities and Futures Commission and Chapter 6 of the SFC’s Guidelines on Online Distribution and Advisory Platforms, and the relevant Frequently Asked Questions."
          }
        ],
        "rationale": "Footnote 8 expressly identifies the sale authorities; it does not reproduce their substantive provisions."
      },
      "question_relation": {
        "status": "NOT_APPLICABLE_TO_THIS_QUESTION",
        "question_hash": "667e02878245fac215d7cc7676acbdd52b486e17dea8e9eed9ea5b37ad03a712",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u32.4805",
            "quote": "A Fund classified as a complex product will be subject to the SFC’s prevailing requirements for the sale of complex products8"
          }
        ],
        "rationale": "The authorities govern sale requirements following classification, whereas the exact question asks whether either retained classification route applies."
      },
      "executable_correspondence": {
        "status": "NOT_APPLICABLE",
        "representation_quotes": [],
        "rationale": "The formula does not assess sale compliance. Omitting implementation of these authorities is outside this question and supplies no permission to disregard them."
      },
      "authority": {
        "status": "MISSING",
        "dependency_ids": [],
        "rationale": "The three named authorities are absent. The circular establishes their identification, but their substantive requirements cannot be assessed; no dependency-to-authority mapping is supplied."
      },
      "followup_questions": [
        "Can Code of Conduct paragraph 5.5, Online Distribution and Advisory Platforms Guidelines chapter 6, and the relevant FAQs applicable at the assessment time be supplied and mapped to dependency IDs?"
      ]
    },
    {
      "claim_id": "claim.8b9221b121dedba945c1b7af",
      "candidate_id": "node.ad3ed6f7c586444ec7213491",
      "source_support": {
        "status": "SUPPORTED",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u21.3779",
            "quote": "On a case-by-case basis, the SFC may also designate a Fund as a complex product, taking into account factors including, without limitation:"
          },
          {
            "unit_id": "d4148dd852cee.u22.4078",
            "quote": "the aggregate direct and indirect exposures to private market assets of the Fund;"
          }
        ],
        "rationale": "Aggregate exposure is expressly a discretionary assessment factor. No separate automatic threshold is stated for that factor."
      },
      "question_relation": {
        "status": "NOT_APPLICABLE_TO_THIS_QUESTION",
        "question_hash": "667e02878245fac215d7cc7676acbdd52b486e17dea8e9eed9ea5b37ad03a712",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u21.3779",
            "quote": "On a case-by-case basis, the SFC may also designate a Fund as a complex product, taking into account factors including, without limitation:"
          }
        ],
        "rationale": "This claim concerns how the SFC exercises discretion. The typed question instead consumes an actual applicable designation. Aggregate exposure remains relevant separately to the automatic route, but that is not the discretionary-factor claim assessed here."
      },
      "executable_correspondence": {
        "status": "NOT_APPLICABLE",
        "representation_quotes": [
          "applicable_sfc_designation: The SFC has actually made a case-specific complex-product designation for this Fund that applies at the assessment time. Unknown designation evidence leaves this fact unknown. (Boolean for an applicable SFC decision concerning the assessed fund)"
        ],
        "rationale": "Implementing the SFC's discretionary consideration of exposure is outside this exact question. The rule records the decision rather than inferring it from a factor."
      },
      "authority": {
        "status": "NONE_DECLARED",
        "dependency_ids": [],
        "rationale": "The retained circular directly establishes this factor."
      },
      "followup_questions": []
    },
    {
      "claim_id": "claim.8c3e8f5b273c84c361a6b058",
      "candidate_id": "node.ad3ed6f7c586444ec7213491",
      "source_support": {
        "status": "SUPPORTED",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u1.5",
            "quote": "private credit and private equity (collectively, private market assets)"
          }
        ],
        "rationale": "The source expressly supplies the collective definition."
      },
      "question_relation": {
        "status": "RELEVANT",
        "question_hash": "667e02878245fac215d7cc7676acbdd52b486e17dea8e9eed9ea5b37ad03a712",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u21.3779",
            "quote": "A Fund will be considered as a complex product if its total direct and indirect exposures to private market assets amount to 50% or more of the Fund’s NAV."
          }
        ],
        "rationale": "The definition specifies the asset categories counted toward the automatic classification threshold."
      },
      "executable_correspondence": {
        "status": "PRESERVES",
        "representation_quotes": [
          "direct_exposure: Aggregate direct exposure to private credit and private equity, measured under the supplied exposure methodology at the assessment time. (Exact common valuation units, identical to those used for indirect_exposure and nav)",
          "indirect_exposure: Aggregate indirect exposure to private credit and private equity through all relevant holdings and instruments, including qualifying exposures beyond the listed examples, measured under the supplied methodology at the assessment time. (Exact common valuation units, identical to those used for direct_exposure and nav)"
        ],
        "rationale": "Both inputs expressly adopt private credit and private equity. This preserves the category definition without verifying the upstream classification or valuation of individual holdings."
      },
      "authority": {
        "status": "NONE_DECLARED",
        "dependency_ids": [],
        "rationale": "No additional external authority is needed for the circular's express definition."
      },
      "followup_questions": []
    },
    {
      "claim_id": "claim.97a2fbda323ec92b399e29d4",
      "candidate_id": "node.ad3ed6f7c586444ec7213491",
      "source_support": {
        "status": "SUPPORTED",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u4.564",
            "quote": "This circular provides guidance to management companies of funds that are authorised by the SFC for offering to the public in Hong Kong (Funds)6 in this regard."
          },
          {
            "unit_id": "d4148dd852cee.u63.8691",
            "quote": "Except for listed closed-ended alternative asset funds (LAFs). For LAFs, please refer to the circular on LAFs:"
          }
        ],
        "rationale": "Footnote 6 excludes LAFs from the defined Fund scope and directs them elsewhere. It does not classify them as non-complex."
      },
      "question_relation": {
        "status": "RELEVANT",
        "question_hash": "667e02878245fac215d7cc7676acbdd52b486e17dea8e9eed9ea5b37ad03a712",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u63.8691",
            "quote": "Except for listed closed-ended alternative asset funds (LAFs)."
          }
        ],
        "rationale": "The exclusion directly defines the population covered by the exact classification question."
      },
      "executable_correspondence": {
        "status": "PRESERVES",
        "representation_quotes": [
          "Scope: all of these conditions hold: [the fact sfc_authorised_public_fund; it is not the case that [the fact is_laf]; [the fact nav] is strictly greater than [integer value 0]]",
          "A false scope returns OUT_OF_SCOPE; an unknown scope returns UNKNOWN; an unknown IF condition returns UNKNOWN without choosing either branch.",
          "A conflicting fact anywhere in the rule dependency closure blocks evaluation with CONFLICT even on an unselected branch."
        ],
        "rationale": "On non-conflicting established facts, a LAF fails scope and returns OUT_OF_SCOPE rather than FALSE. A dependency conflict blocks evaluation instead. Neither outcome asserts that LAFs are non-complex."
      },
      "authority": {
        "status": "NONE_DECLARED",
        "dependency_ids": [],
        "rationale": "The exclusion is established by this circular. The separate LAF circular is missing but is needed only to determine excluded LAFs' treatment beyond this question."
      },
      "followup_questions": [
        "If classification of excluded LAFs is required, can the separate LAF circular identified in footnote 6 as 25EC9 be supplied and mapped to a dependency ID?"
      ]
    },
    {
      "claim_id": "claim.a1e997fc60c27a3a04976a4a",
      "candidate_id": "node.ad3ed6f7c586444ec7213491",
      "source_support": {
        "status": "SUPPORTED",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u49.6955",
            "quote": "For existing SFC-authorised funds that may have direct or indirect exposure to private market assets, fund managers are expected to undertake a review of their funds, take appropriate actions including updating the Fund’s offering documents as soon as practicable, and ensure necessary and proper communications with the distributors in light of the guidance provided under this circular (in particular, with respect to paragraphs 9 and 10 above)."
          }
        ],
        "rationale": "The source supports the expectation and timing for document updates. It supplies neither a fixed implementation date nor an express classification grace period."
      },
      "question_relation": {
        "status": "NOT_APPLICABLE_TO_THIS_QUESTION",
        "question_hash": "667e02878245fac215d7cc7676acbdd52b486e17dea8e9eed9ea5b37ad03a712",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u49.6955",
            "quote": "take appropriate actions including updating the Fund’s offering documents as soon as practicable"
          }
        ],
        "rationale": "This governs managers' actions and document-update timing, not whether either classification route applies at the assessment time."
      },
      "executable_correspondence": {
        "status": "NOT_APPLICABLE",
        "representation_quotes": [],
        "rationale": "Document-update compliance is outside this classification question. Its omission supplies no grace period or exemption from classification."
      },
      "authority": {
        "status": "NONE_DECLARED",
        "dependency_ids": [],
        "rationale": "The retained source directly states this expectation."
      },
      "followup_questions": []
    },
    {
      "claim_id": "claim.a35b513ae275b5c6620778c9",
      "candidate_id": "node.ad3ed6f7c586444ec7213491",
      "source_support": {
        "status": "SUPPORTED",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u21.3779",
            "quote": "On a case-by-case basis, the SFC may also designate a Fund as a complex product, taking into account factors including, without limitation:"
          },
          {
            "unit_id": "d4148dd852cee.u24.4176",
            "quote": "the Fund's overall investment strategy, portfolio composition, and liquidity and/or risk profile;"
          }
        ],
        "rationale": "The source expressly lists these considerations for case-specific designation."
      },
      "question_relation": {
        "status": "NOT_APPLICABLE_TO_THIS_QUESTION",
        "question_hash": "667e02878245fac215d7cc7676acbdd52b486e17dea8e9eed9ea5b37ad03a712",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u29.4630",
            "quote": "In assessing whether the complex product designation is warranted7, the SFC will adopt a holistic approach taking into account the specific circumstances of the case."
          }
        ],
        "rationale": "These considerations explain the SFC's discretionary assessment. The exact question uses an actual applicable designation, not a prediction or reconstruction of the SFC's decision."
      },
      "executable_correspondence": {
        "status": "NOT_APPLICABLE",
        "representation_quotes": [
          "applicable_sfc_designation: The SFC has actually made a case-specific complex-product designation for this Fund that applies at the assessment time. Unknown designation evidence leaves this fact unknown. (Boolean for an applicable SFC decision concerning the assessed fund)"
        ],
        "rationale": "Implementing portfolio and strategy judgments is outside this classification question. The formula appropriately provides no automatic factor-based substitute for a designation."
      },
      "authority": {
        "status": "NONE_DECLARED",
        "dependency_ids": [],
        "rationale": "The circular directly establishes the listed considerations."
      },
      "followup_questions": []
    },
    {
      "claim_id": "claim.a633deabeece62d9839204f7",
      "candidate_id": "node.ad3ed6f7c586444ec7213491",
      "source_support": {
        "status": "SUPPORTED",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u32.4805",
            "quote": "A Fund classified as a complex product will be subject to the SFC’s prevailing requirements for the sale of complex products8"
          },
          {
            "unit_id": "d4148dd852cee.u65.9044",
            "quote": "Paragraph 5.5 of the SFC’s Code of Conduct for Persons Licensed by or Registered with the Securities and Futures Commission and Chapter 6 of the SFC’s Guidelines on Online Distribution and Advisory Platforms, and the relevant Frequently Asked Questions."
          }
        ],
        "rationale": "The body and footnote support the obligation and incorporation. The complete incorporated requirements and qualifications remain unavailable."
      },
      "question_relation": {
        "status": "NOT_APPLICABLE_TO_THIS_QUESTION",
        "question_hash": "667e02878245fac215d7cc7676acbdd52b486e17dea8e9eed9ea5b37ad03a712",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u32.4805",
            "quote": "A Fund classified as a complex product will be subject to the SFC’s prevailing requirements for the sale of complex products8"
          }
        ],
        "rationale": "The obligation follows classification. It does not determine whether either retained route requires classification."
      },
      "executable_correspondence": {
        "status": "NOT_APPLICABLE",
        "representation_quotes": [],
        "rationale": "Sale-requirement compliance is outside this exact question. A classification result cannot be interpreted as satisfying that separate obligation."
      },
      "authority": {
        "status": "MISSING",
        "dependency_ids": [],
        "rationale": "The incorporated Code provision, Guidelines chapter and FAQs are absent, and their names cannot be mapped to the supplied unbound dependency IDs."
      },
      "followup_questions": [
        "Can the prevailing Code of Conduct paragraph 5.5, Online Distribution and Advisory Platforms Guidelines chapter 6, and relevant FAQs be supplied for the assessment time and mapped to dependency IDs?"
      ]
    },
    {
      "claim_id": "claim.a7f7ba358f7b8f4aadc66d7f",
      "candidate_id": "node.ad3ed6f7c586444ec7213491",
      "source_support": {
        "status": "SUPPORTED",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u60.8163",
            "quote": "BDCs are close-ended funds registered under the US Investment Company Act of 1940, which primarily invest in debt and equity of small and mid-sized companies in the US."
          }
        ],
        "rationale": "The claim accurately attributes this description to the circular. It does not independently establish the US legal status of any particular entity."
      },
      "question_relation": {
        "status": "RELEVANT",
        "question_hash": "667e02878245fac215d7cc7676acbdd52b486e17dea8e9eed9ea5b37ad03a712",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u1.5",
            "quote": "indirect exposures2 including through investments in business development companies (BDCs)3, collateralised loan obligations (CLOs)4 or financial derivative instruments5."
          }
        ],
        "rationale": "The description informs identification of an expressly listed indirect-exposure channel used in the threshold input. Holding a BDC is not itself a classification trigger."
      },
      "executable_correspondence": {
        "status": "OMITS",
        "representation_quotes": [
          "indirect_exposure: Aggregate indirect exposure to private credit and private equity through all relevant holdings and instruments, including qualifying exposures beyond the listed examples, measured under the supplied methodology at the assessment time. (Exact common valuation units, identical to those used for direct_exposure and nav)",
          "Supplied classifications requiring judgment: is_laf, direct_exposure, indirect_exposure, nav, applicable_sfc_designation. Their assessment is not implemented by this formula."
        ],
        "rationale": "The executable does not encode the BDC description or determine exposure through BDC holdings. Correct upstream inclusion remains possible; this is an input-assessment omission, not proof that BDC exposure is excluded."
      },
      "authority": {
        "status": "NONE_DECLARED",
        "dependency_ids": [],
        "rationale": "No additional authority is required to establish what the circular says. Independently determining a specific entity's US legal status would be a different inquiry."
      },
      "followup_questions": [
        "How does the upstream methodology identify BDC holdings and measure their contribution to aggregate private-market exposure?"
      ]
    },
    {
      "claim_id": "claim.ae70d5959e88ef0af314b6c1",
      "candidate_id": "node.ad3ed6f7c586444ec7213491",
      "source_support": {
        "status": "SUPPORTED",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u39.5617",
            "quote": "They should also ensure that the distributors chosen are appropriate for covering the target market identified, have the necessary product knowledge to understand the Fund (including whether the Fund is a complex product) and to assign an appropriate product risk rating (if applicable) for the Fund, and advise investors accordingly."
          }
        ],
        "rationale": "The source expressly supports the duty, including the qualification that a product risk rating is assigned where applicable."
      },
      "question_relation": {
        "status": "NOT_APPLICABLE_TO_THIS_QUESTION",
        "question_hash": "667e02878245fac215d7cc7676acbdd52b486e17dea8e9eed9ea5b37ad03a712",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u39.5617",
            "quote": "have the necessary product knowledge to understand the Fund (including whether the Fund is a complex product)"
          }
        ],
        "rationale": "Distributor knowledge uses the classification outcome but does not create a classification route. The exact question does not assess distributor selection or advice."
      },
      "executable_correspondence": {
        "status": "NOT_APPLICABLE",
        "representation_quotes": [],
        "rationale": "Distributor selection, knowledge, risk rating and investor advice are outside this classification question. The output cannot establish compliance with these duties."
      },
      "authority": {
        "status": "NONE_DECLARED",
        "dependency_ids": [],
        "rationale": "The stated duty is directly supported here. The separately referenced Internal Product Approval Process circular is missing but is needed only for a broader assessment of its incorporated requirements."
      },
      "followup_questions": [
        "If broader distributor-selection compliance is required, can the Internal Product Approval Process circular referenced in units d4148dd852cee.u36.5149 and d4148dd852cee.u66.9304, updated on 4 March 2016, be supplied and mapped to a dependency ID?"
      ]
    }
  ],
  "additional_concerns": [
    "The executable adds a scope condition absent from the retained source: \"[the fact nav] is strictly greater than [integer value 0]\". On non-conflicting facts, zero or negative NAV produces OUT_OF_SCOPE even if an applicable SFC designation is established. Positive NAV may be an input-validity assumption, but the circular does not establish it as a legal exclusion. The treatment of these cases remains unresolved.",
